// TypeScript Version: 4.1

/**
* Formats an array of reference tokens into a JSON Pointer string.
*
* ## Notes
*
* -   Implements formatting per RFC 6901.
* -   An empty array returns an empty string (refers to the root of the document).
* -   Escape sequences are encoded: `~` is escaped to `~0` before `/` is escaped to `~1`.
*
* @param tokens - array of reference tokens
* @throws must provide an array of strings
* @returns JSON Pointer string
*
* @example
* var ptr = format( [ 'foo', 'bar' ] );
* // returns '/foo/bar'
*
* @example
* var ptr = format( [ 'a/b', 'c~d' ] );
* // returns '/a~1b/c~0d'
*
* @example
* var ptr = format( [] );
* // returns ''
*/
declare function format( tokens: Array<string> ): string;


// EXPORTS //

export = format;
